import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.BvlN9b-o.js";const u=JSON.parse('{"title":"Maintain developer documentation","description":"","frontmatter":{"docLocale":"en","counterpart":"/guides/documentation","contentType":"guide","prev":false,"next":{"text":"Publish your documentation site","link":"/en/getting-started/publish-docs"}},"headers":[],"relativePath":"en/guides/documentation.md","filePath":"en/guides/documentation.md"}'),s={name:"en/guides/documentation.md"};function o(r,e,d,c,l,p){return t(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="maintain-developer-documentation" tabindex="-1">Maintain developer documentation <a class="header-anchor" href="#maintain-developer-documentation" aria-label="Permalink to &quot;Maintain developer documentation&quot;">​</a></h1><p>Ship documentation with public capabilities. When implementing your SaaS feature, update its tutorials, code examples, translations and verification entry points together.</p><h2 id="choose-the-page-type" tabindex="-1">Choose the page type <a class="header-anchor" href="#choose-the-page-type" aria-label="Permalink to &quot;Choose the page type&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Start with</th><th>Completion check</th></tr></thead><tbody><tr><td>Tutorial</td><td>Previous code state, complete change and result</td><td>The same business code continues into the next stage</td></tr><tr><td>Guide</td><td>Development goal, prerequisites, public interface and minimal implementation</td><td>The task works when entered independently</td></tr><tr><td>Concept</td><td>Definition, real relationship diagram and minimal code</td><td>Readers know when to use it, why and its boundaries</td></tr><tr><td>Reference</td><td>Fact source, categories, parameters, returns and limits</td><td>Readers can locate the current contract</td></tr></tbody></table><p>Backend tutorials focus on files, code, requests and results. State working directory, dependencies, complete changes and expected responses. Show the runnable path before explaining details.</p><h2 id="register-bilingual-pages" tabindex="-1">Register bilingual pages <a class="header-anchor" href="#register-bilingual-pages" aria-label="Permalink to &quot;Register bilingual pages&quot;">​</a></h2><p>Markdown is the editable source. Add a same-named <code>.en.md</code> beside Chinese and register stable id, both titles, sources, published route, group and page type in <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/docs/site.json" target="_blank" rel="noreferrer">site.json</a>.</p><p>Use chapter ids in <code>previous</code> / <code>next</code> for a sequence. Without an explicit relationship, disable automatic neighbors so a next chapter does not lead to an unrelated guide.</p><p>Keep historical published routes stable. Move sources with their links and site declarations. Rendering localizes registered destinations, and the footer links to the build source commit.</p><h2 id="keep-examples-runnable" tabindex="-1">Keep examples runnable <a class="header-anchor" href="#keep-examples-runnable" aria-label="Permalink to &quot;Keep examples runnable&quot;">​</a></h2><p>Use <code>&lt;&lt;&lt;</code> to include checked source. State insertion locations, compile or execute examples through the same verification entry, and link fragments to complete code. Rust/OpenAPI owns DTOs; Settings/FIELDS owns defaults.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span></code></pre></div><p>Business HTTP or public-capability checks verify success, denial and critical failures. Browser checks verify reading and navigation. Building successfully does not establish that the teaching steps work.</p><h2 id="example-ownership" tabindex="-1">Example ownership <a class="header-anchor" href="#example-ownership" aria-label="Permalink to &quot;Example ownership&quot;">​</a></h2><p>Register specific tutorials and code in the example manifest. Put example links on shared pages inside registered markers. Removing the example removes its content and navigation while preserving buildable Core documentation.</p><h2 id="maintainer-records" tabindex="-1">Maintainer records <a class="header-anchor" href="#maintainer-records" aria-label="Permalink to &quot;Maintainer records&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/CONTEXT.md" target="_blank" rel="noreferrer">CONTEXT</a> owns terms, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/ARCHITECTURE.md" target="_blank" rel="noreferrer">architecture rules</a> describe dependencies and runtime contracts, and <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/docs/adr/0002-executable-removable-reference.md" target="_blank" rel="noreferrer">ADRs</a> record decisions. <a href="./../architecture/v1-coverage">Capability coverage and historical acceptance</a> records evidence. The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/docs/agents/development-flow.md" target="_blank" rel="noreferrer">development flow</a> and <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/docs/agents/documentation.md" target="_blank" rel="noreferrer">author rules</a> describe maintenance; GitHub Issues owns live implementation state.</p><p>Use <a href="./../getting-started/publish-docs">publish documentation</a> for your own site.</p><hr><p>Source version：<code>e87f840d6dfc</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/docs/guides/maintain-docs.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,20)])])}const m=a(s,[["render",o]]);export{u as __pageData,m as default};
